    "changed_decision": "yes",
    "explanation": "The historical evidence of confounding artifacts (FAM:SF-TMP-009) and talent-driven null results (FAM:SF-APPS-087) made me realize that a naive before-after comparison of shot mix after lineup changes would likely be confounded and produce artifacts. Therefore, I changed from a potential 'proceed' to 'proceed_with_changes', requiring pre-registered controls (player fixed effects, opponent lineup, composite outcome) and placebo tests."
  },
  "testability": {
    "p_testable": 0.6,
    "blocking_constraints": [
      {
        "code": "CONFOUNDING",
        "text": "Substitutions are endogenous: they correlate with score, time, fatigue, and recent performance, making it difficult to isolate the causal effect of the lineup change on shot mix."
      },
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "Rare lineups or short stints may have too few possessions to estimate shot mix reliably. Even with three seasons, the power to detect small shifts in secondary shot categories may be low."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "If many shot categories are tested separately without a pre-specified composite index, false positive rates will be inflated."
      },
      {
        "code": "MEASURE_RELIABILITY",
        "text": "Play-type and shot-type classifications derived from play-by-play may contain errors that attenuate true effects."
      }
    ]
  },
  "prior_work": {
    "already_answered": "no",
    "cited": [
      "FAM:SF34",
      "FAM:SF-TMP-009",
      "FAM:SF32",
      "FAM:SF-APPS-087"
    ],
    "summary": "Prior work has not directly tested whether changing the offensive five moves shot mix. It has established that shot-mix shifts exist (opponent-driven), confounds are strong, and artifacts are common in lineup-level analyses, motivating a cautious design."
  },
  "risks": [
    {
      "code": "CONFOUNDING",
      "text": "Endogenous substitutions and simultaneous changes in opponent lineup, score, and game script can bias estimates of the personnel effect."
    },
    {
      "code": "ARTIFACT",
      "text": "Without adequate controls, observed effects may replicate the artifact patterns seen in SF-TMP-009 (shooter-level confound) or SF32 (infeasible targets)."
    },
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "Power may be insufficient for rare shot types, and the overall effect size is unknown."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "Testing many shot-type outcomes increases false positive risk if not corrected."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "Shot classification errors from play-by-play parsing could dilute true effects."
    }
  ],
  "predicted_outcome": {
    "supported": 0.2,
    "rejected": 0.3,
    "untestable": 0.1,
    "artifact": 0.1,
    "uncertain": 0.3
  },
  "decision": "proceed_with_changes",
  "design": {
    "estimand": "The causal effect of changing the offensive five-man lineup (substituting players) on the offense's shot-type mix in subsequent possessions, controlling for game context and opponent lineup.",
    "unit": "per-possession shot type (e.g., 3PA flag, rim attempt flag) or possession-level shot distance category.",
    "sample": "All offensive possessions from 2022-23 through 2024-25 where the offensive five changed during a game, excluding end-of-quarter/shot-clock violations, garbage time (total possessions after the change vs. equal-length window before).",
    "power": "Based on FAM:SF34, a composite shot mix index may need ~1M possessions for a 0.2 SD shift. With ~1.5M eligible lineup-change possessions across three seasons, power >80% for a primary composite index. Secondary outcomes will have lower power; a simulation using actual substitution patterns is required before finalizing.",
    "controls": "Score margin, time remaining, period, days since last game, home/away, offensive and defensive team season fixed effects, opponent defensive lineup measured by average defensive rating of the five defenders on the floor, and player fixed effects (including an indicator for the specific substitution pair).",
    "falsification": "Placebo test 1: Re-insert the same offensive five after a brief time-out or quarter break (no actual personnel change) and compare shot mix before vs. after; any observed effect suggests regression to the mean or time trends. Placebo test 2: Show that pre-change shot mix does not predict the direction of upcoming lineup changes, reducing concern about reverse causality.",
    "multiplicity": "Primary outcome: a single pre-registered composite shot mix index (first principal component of the possession-level shot type vector, or a weighted sum based on league-wide 2021-22 variances). Secondary outcomes: individual shot types (3PA, rim attempts, midrange) tested with Holm-Bonferroni correction.",
    "decision_rule": "Reject the null hypothesis that the coefficient on the change in lineup composite shot propensity (mean shot propensity of incoming minus outgoing five) is zero at α=0.05, with a one-sided test expecting a positive coefficient. Interpret effect size relative to league average variation.",
    "data_version": "NBA stats API snapshots as of 2026-11-02, covering 2022-23, 2023-24, 2024-25 regular seasons and playoffs."
  }
}

